-- Temporal redundancy view for : d_hcpcs_history
/* QUERYNAME=RedundancyUnfoldfold */
create or replace view "mimiciv_hosp@V@UHF".d_hcpcs_history_red_ret as
  with unpack as
    (
      select "code"
           , "UHF".unfold("validTime") as point
      from "mimiciv_hosp@V@UHF".d_hcpcs_history
    ),
    anomalies as
      (
        select "code"
             , point
             , count(*) as count
        from unpack
        group by "code", point
        having count(*) > 1
      )
  select "code"
       , unnest("UHF".fold("UHF".interval_cons(point,point))) as redundancies
       , count
  from anomalies
  group by "code", count;

-- Temporal redundancy view for : d_hcpcs_history
/* QUERYNAME=RedundancyWindowFunction */
create or replace view "mimiciv_hosp@V@UHF".d_hcpcs_history_rwf_red as
  with T1 (Start_ts, End_ts, ts, code) as (
    select
      1,
      0,
      lower("validTime"),
      "code"
    from "mimiciv_hosp@V@UHF".d_hcpcs_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "code"
    from "mimiciv_hosp@V@UHF".d_hcpcs_history
  ),
  T2 (Crt_Total_ts, ts, code) as (
    select
      sum(Start_ts) over (partition by "code" order by ts, End_ts rows unbounded preceding)
      - sum(End_ts) over (partition by "code" order by ts, End_ts rows unbounded preceding) as Crt_Total_ts,
      ts,
      "code"
    from T1
  )
  select
    "code",
    redundancies,
    Crt_Total_ts
  from
  (
    select
      Crt_Total_ts,
      "code",
      int4range(ts, lead(ts) over (partition by "code" order by ts )) as redundancies
    from T2
  ) tt
  where Crt_Total_ts >1 and redundancies <> 'empty' and upper(redundancies) is not null;

-- Temporal contradiction view for d_hcpcs_category_history
/* QUERYNAME=ContradictionUnfoldfold */
create or replace view "mimiciv_hosp@V@UHF".rctr_d_hcpcs_category_history as
  with unpack as
    (
      select "code"
        , "category"
        , "UHF".unfold("validTime") as point
      from "mimiciv_hosp@V@UHF".d_hcpcs_category_history
    ),
    anomalies as
      (
        select "code"
             , point
             , array_agg(distinct "category") as contradictions
        from unpack
        group by "code", point
        having count("category") > 1
      )
  select "code"
       , contradictions
       , unnest("UHF".fold("UHF".interval_cons(point,point))) as during
  from anomalies
  where array_length(contradictions, 1) > 1
  group by "code", contradictions;

-- Temporal contradiction view for : d_hcpcs_category_history
/* QUERYNAME=ContradictionWindowFunction */
create or replace view "mimiciv_hosp@V@UHF".wf_rctr_d_hcpcs_category_history as
  with T1 (Start_ts, End_ts, ts, code) as (
    select
      1,
      0,
      lower("validTime"),
      "code"
    from "mimiciv_hosp@V@UHF".d_hcpcs_category_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "code"
    from "mimiciv_hosp@V@UHF".d_hcpcs_category_history
  ),
  T2 (Crt_Total_ts, ts, code) as (
    select
      sum(Start_ts) over (
        partition by "code"
        order by ts, End_ts
        rows unbounded preceding
      )
      - sum(End_ts) over (
        partition by "code"
        order by ts, End_ts
        rows unbounded preceding
      ) as Crt_Total_ts,
      ts,
      "code"
    from T1
  )
  select
    r."code",
    array_agg(distinct s."category") as category_contradictions,
    r.contradictions
  from "mimiciv_hosp@V@UHF".d_hcpcs_category_history as s
  inner join (
    select
      "code",
      contradictions
    from (
      select
        Crt_Total_ts,
        "code",
        int4range(ts, lead(ts) over (
          partition by "code"
          order by ts
        )) as contradictions
      from T2
    ) tt
    where Crt_Total_ts > 0
      and contradictions <> 'empty'
      and upper(contradictions) is not null
  ) r
  on (
    s."code" = r."code"
    and r.contradictions <@ s."validTime"
  )
  group by r."code", r.contradictions
  having count(distinct s."category") > 1;

-- Temporal denseness view for d_hcpcs_category_history <-> d_hcpcs_history
/* QUERYNAME=DensenessUnfoldfold */
create or replace view "mimiciv_hosp@V@UHF".dert_d_hcpcs_category_history_d_hcpcs_history as
  with unpack as
    (
      select "code"
           , "UHF".unfold("validTime") as point
           , 'd_hcpcs_category_history' as source
      from "mimiciv_hosp@V@UHF".d_hcpcs_category_history
      union
      select "code"
           , "UHF".unfold("validTime") as point
           , 'd_hcpcs_history' as source
      from "mimiciv_hosp@V@UHF".d_hcpcs_history
    ),
    anomalies as
    (
      select "code"
           , point
           , array_agg(distinct source) as sources
      from unpack
      group by "code", point
    )
  select "code"
       , unnest("UHF".fold("UHF".interval_cons(point,point))) as during
       , sources
  from anomalies
  where array_length(sources, 1) < 2
  group by "code", sources;

-- Temporal denseness view for d_hcpcs_category_history <-> d_hcpcs_history
/* QUERYNAME=DensenessUnfoldfold */
create or replace view "mimiciv_hosp@V@UHF".wf_d_hcpcs_category_history_d_hcpcs_history as
  with T1 (Start_ts, End_ts, ts, code, "validTime", source) as (
    select
      1,
      0,
      lower("validTime"),
      "code",
      "validTime",
      'd_hcpcs_category_history' as source
    from "mimiciv_hosp@V@UHF".d_hcpcs_category_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "code",
      "validTime",
      'd_hcpcs_category_history' as source
    from "mimiciv_hosp@V@UHF".d_hcpcs_category_history
    union all
    select
      1,
      0,
      lower("validTime"),
      "code",
      "validTime",
      'd_hcpcs_history' as source
    from "mimiciv_hosp@V@UHF".d_hcpcs_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "code",
      "validTime",
      'd_hcpcs_history' as source
    from "mimiciv_hosp@V@UHF".d_hcpcs_history
  ),
  T2 as (
    select distinct
      "code",
      "validTime",
      source,
      int4range(ts, lead(ts) over (
        partition by "code"
        order by ts
      )) as T
    from T1
    window w as (partition by "code" order by ts)
  ),
  anomalies as (
    select
      t21."code",
      t22.source,
      t21.t,
      t22."validTime"
    from T2 as t21
    join T2 as t22 using ("code")
    where
      t21.t <@ t22."validTime"
      and t21.t <> 'empty'
  )
  select
    "code",
    T,
    array_agg(distinct source) as sources
  from anomalies
  group by "code", T
  having array_length(array_agg(distinct source), 1) = 1;

