       , sources
  from anomalies
  where array_length(sources, 1) < 2
  group by "labevent_id", sources;

-- Temporal denseness view for labevents_ref_range_upper_history <-> labevents_history
/* QUERYNAME=DensenessUnfoldfold */
create or replace view "mimiciv_hosp@V@UHF".wf_labevents_ref_range_upper_history_labevents_history as
  with T1 (Start_ts, End_ts, ts, labevent_id, "validTime", source) as (
    select
      1,
      0,
      lower("validTime"),
      "labevent_id",
      "validTime",
      'labevents_ref_range_upper_history' as source
    from "mimiciv_hosp@V@UHF".labevents_ref_range_upper_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "labevent_id",
      "validTime",
      'labevents_ref_range_upper_history' as source
    from "mimiciv_hosp@V@UHF".labevents_ref_range_upper_history
    union all
    select
      1,
      0,
      lower("validTime"),
      "labevent_id",
      "validTime",
      'labevents_history' as source
    from "mimiciv_hosp@V@UHF".labevents_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "labevent_id",
      "validTime",
      'labevents_history' as source
    from "mimiciv_hosp@V@UHF".labevents_history
  ),
  T2 as (
    select distinct
      "labevent_id",
      "validTime",
      source,
      int4range(ts, lead(ts) over (
        partition by "labevent_id"
        order by ts
      )) as T
    from T1
    window w as (partition by "labevent_id" order by ts)
  ),
  anomalies as (
    select
      t21."labevent_id",
      t22.source,
      t21.t,
      t22."validTime"
    from T2 as t21
    join T2 as t22 using ("labevent_id")
    where
      t21.t <@ t22."validTime"
      and t21.t <> 'empty'
  )
  select
    "labevent_id",
    T,
    array_agg(distinct source) as sources
  from anomalies
  group by "labevent_id", T
  having array_length(array_agg(distinct source), 1) = 1;

