-- Temporal contradiction view for : labevents_flag_history
/* QUERYNAME=ContradictionWindowFunction */
create or replace view "mimiciv_hosp@V@UHF".wf_rctr_labevents_flag_history as
  with T1 (Start_ts, End_ts, ts, labevent_id) as (
    select
      1,
      0,
      lower("validTime"),
      "labevent_id"
    from "mimiciv_hosp@V@UHF".labevents_flag_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "labevent_id"
    from "mimiciv_hosp@V@UHF".labevents_flag_history
  ),
  T2 (Crt_Total_ts, ts, labevent_id) as (
    select
      sum(Start_ts) over (
        partition by "labevent_id"
        order by ts, End_ts
        rows unbounded preceding
      )
      - sum(End_ts) over (
        partition by "labevent_id"
        order by ts, End_ts
        rows unbounded preceding
      ) as Crt_Total_ts,
      ts,
      "labevent_id"
    from T1
  )
  select
    r."labevent_id",
    array_agg(distinct s."flag") as flag_contradictions,
    r.contradictions
  from "mimiciv_hosp@V@UHF".labevents_flag_history as s
  inner join (
    select
      "labevent_id",
      contradictions
    from (
      select
        Crt_Total_ts,
        "labevent_id",
        int4range(ts, lead(ts) over (
          partition by "labevent_id"
          order by ts
        )) as contradictions
      from T2
    ) tt
    where Crt_Total_ts > 0
      and contradictions <> 'empty'
      and upper(contradictions) is not null
  ) r
  on (
    s."labevent_id" = r."labevent_id"
    and r.contradictions <@ s."validTime"
  )
  group by r."labevent_id", r.contradictions
  having count(distinct s."flag") > 1;

