      1,
      upper("validTime"),
      "transfer_id"
    from "mimiciv_hosp@V@UHF".transfers_outtime_history
  ),
  T2 (Crt_Total_ts, ts, transfer_id) as (
    select
      sum(Start_ts) over (
        partition by "transfer_id"
        order by ts, End_ts
        rows unbounded preceding
      )
      - sum(End_ts) over (
        partition by "transfer_id"
        order by ts, End_ts
        rows unbounded preceding
      ) as Crt_Total_ts,
      ts,
      "transfer_id"
    from T1
