create or replace view "mimiciv_hosp@V@UHF".wf_drgcodes_drg_severity_history_drgcodes_history as
  with T1 (Start_ts, End_ts, ts, subject_id, hadm_id, drg_code, "validTime", source) as (
    select
      1,
      0,
      lower("validTime"),
      "subject_id", "hadm_id", "drg_code",
      "validTime",
      'drgcodes_drg_severity_history' as source
    from "mimiciv_hosp@V@UHF".drgcodes_drg_severity_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "subject_id", "hadm_id", "drg_code",
      "validTime",
      'drgcodes_drg_severity_history' as source
    from "mimiciv_hosp@V@UHF".drgcodes_drg_severity_history
    union all
    select
      1,
      0,
      lower("validTime"),
      "subject_id", "hadm_id", "drg_code",
      "validTime",
      'drgcodes_history' as source
    from "mimiciv_hosp@V@UHF".drgcodes_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "subject_id", "hadm_id", "drg_code",
      "validTime",
      'drgcodes_history' as source
    from "mimiciv_hosp@V@UHF".drgcodes_history
  ),
  T2 as (
    select distinct
      "subject_id", "hadm_id", "drg_code",
      "validTime",
      source,
      int4range(ts, lead(ts) over (
        partition by "subject_id", "hadm_id", "drg_code"
        order by ts
      )) as T
    from T1
    window w as (partition by "subject_id", "hadm_id", "drg_code" order by ts)
  ),
  anomalies as (
    select
      t21."subject_id", t21."hadm_id", t21."drg_code",
      t22.source,
      t21.t,
      t22."validTime"
    from T2 as t21
    join T2 as t22 using ("subject_id", "hadm_id", "drg_code")
    where
      t21.t <@ t22."validTime"
      and t21.t <> 'empty'
  )
  select
    "subject_id", "hadm_id", "drg_code",
    T,
    array_agg(distinct source) as sources
  from anomalies
  group by "subject_id", "hadm_id", "drg_code", T
  having array_length(array_agg(distinct source), 1) = 1;

-- Temporal redundancy view for : drgcodes_drg_severity_history
