-- Temporal redundancy view for : drgcodes_drg_severity_history
/* QUERYNAME=RedundancyWindowFunction */
create or replace view "mimiciv_hosp@V@UHF".drgcodes_drg_severity_history_rwf_red as
  with T1 (Start_ts, End_ts, ts, subject_id, hadm_id, drg_code, drg_severity) as (
    select
      1,
      0,
      lower("validTime"),
      "subject_id", "hadm_id", "drg_code", "drg_severity"
    from "mimiciv_hosp@V@UHF".drgcodes_drg_severity_history
    union all
