      "subject_id", "hadm_id", "drg_code", "drg_severity"
    from "mimiciv_hosp@V@UHF".drgcodes_drg_severity_history
  ),
  T2 (Crt_Total_ts, ts, subject_id, hadm_id, drg_code, drg_severity) as (
    select
      sum(Start_ts) over (partition by "subject_id", "hadm_id", "drg_code", "drg_severity" order by ts, End_ts rows unbounded preceding)
      - sum(End_ts) over (partition by "subject_id", "hadm_id", "drg_code", "drg_severity" order by ts, End_ts rows unbounded preceding) as Crt_Total_ts,
      ts,
      "subject_id", "hadm_id", "drg_code", "drg_severity"
    from T1
  )
  select
