      int4range(ts, lead(ts) over (partition by "subject_id", "hadm_id", "drg_code", "drg_severity" order by ts )) as redundancies
    from T2
  ) tt
  where Crt_Total_ts >1 and redundancies <> 'empty' and upper(redundancies) is not null;

-- Temporal contradiction view for drgcodes_drg_mortality_history
/* QUERYNAME=ContradictionUnfoldfold */
create or replace view "mimiciv_hosp@V@UHF".rctr_drgcodes_drg_mortality_history as
  with unpack as
    (
      select "subject_id", "hadm_id", "drg_code"
        , "drg_mortality"
        , "UHF".unfold("validTime") as point
      from "mimiciv_hosp@V@UHF".drgcodes_drg_mortality_history
    ),
    anomalies as
      (
        select "subject_id", "hadm_id", "drg_code"
             , point
             , array_agg(distinct "drg_mortality") as contradictions
        from unpack
        group by "subject_id", "hadm_id", "drg_code", point
        having count("drg_mortality") > 1
      )
  select "subject_id", "hadm_id", "drg_code"
       , contradictions
       , unnest("UHF".fold("UHF".interval_cons(point,point))) as during
  from anomalies
  where array_length(contradictions, 1) > 1
  group by "subject_id", "hadm_id", "drg_code", contradictions;

-- Temporal contradiction view for : drgcodes_drg_mortality_history
/* QUERYNAME=ContradictionWindowFunction */
create or replace view "mimiciv_hosp@V@UHF".wf_rctr_drgcodes_drg_mortality_history as
  with T1 (Start_ts, End_ts, ts, subject_id, hadm_id, drg_code) as (
    select
      1,
      0,
      lower("validTime"),
      "subject_id", "hadm_id", "drg_code"
    from "mimiciv_hosp@V@UHF".drgcodes_drg_mortality_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "subject_id", "hadm_id", "drg_code"
    from "mimiciv_hosp@V@UHF".drgcodes_drg_mortality_history
  ),
  T2 (Crt_Total_ts, ts, subject_id, hadm_id, drg_code) as (
    select
      sum(Start_ts) over (
        partition by "subject_id", "hadm_id", "drg_code"
        order by ts, End_ts
        rows unbounded preceding
      )
      - sum(End_ts) over (
        partition by "subject_id", "hadm_id", "drg_code"
        order by ts, End_ts
        rows unbounded preceding
      ) as Crt_Total_ts,
      ts,
      "subject_id", "hadm_id", "drg_code"
    from T1
  )
  select
    r."subject_id", r."hadm_id", r."drg_code",
    array_agg(distinct s."drg_mortality") as drg_mortality_contradictions,
    r.contradictions
  from "mimiciv_hosp@V@UHF".drgcodes_drg_mortality_history as s
  inner join (
    select
      "subject_id", "hadm_id", "drg_code",
      contradictions
    from (
      select
        Crt_Total_ts,
        "subject_id", "hadm_id", "drg_code",
        int4range(ts, lead(ts) over (
          partition by "subject_id", "hadm_id", "drg_code"
          order by ts
        )) as contradictions
      from T2
    ) tt
    where Crt_Total_ts > 0
      and contradictions <> 'empty'
      and upper(contradictions) is not null
  ) r
  on (
    s."subject_id" = r."subject_id"
        and s."hadm_id" = r."hadm_id"
        and s."drg_code" = r."drg_code"
    and r.contradictions <@ s."validTime"
  )
  group by r."subject_id", r."hadm_id", r."drg_code", r.contradictions
  having count(distinct s."drg_mortality") > 1;

