create or replace view "mimiciv_hosp@V@UHF".pharmacy_status_history_red_ret as
  with unpack as
    (
      select "pharmacy_id", "status"
           , "UHF".unfold("validTime") as point
      from "mimiciv_hosp@V@UHF".pharmacy_status_history
    ),
    anomalies as
      (
        select "pharmacy_id", "status"
             , point
             , count(*) as count
        from unpack
        group by "pharmacy_id", "status", point
        having count(*) > 1
      )
  select "pharmacy_id", "status"
       , unnest("UHF".fold("UHF".interval_cons(point,point))) as redundancies
       , count
  from anomalies
  group by "pharmacy_id", "status", count;

-- Temporal redundancy view for : pharmacy_status_history
/* QUERYNAME=RedundancyWindowFunction */
create or replace view "mimiciv_hosp@V@UHF".pharmacy_status_history_rwf_red as
  with T1 (Start_ts, End_ts, ts, pharmacy_id, status) as (
    select
      1,
      0,
      lower("validTime"),
      "pharmacy_id", "status"
    from "mimiciv_hosp@V@UHF".pharmacy_status_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "pharmacy_id", "status"
    from "mimiciv_hosp@V@UHF".pharmacy_status_history
  ),
  T2 (Crt_Total_ts, ts, pharmacy_id, status) as (
    select
      sum(Start_ts) over (partition by "pharmacy_id", "status" order by ts, End_ts rows unbounded preceding)
      - sum(End_ts) over (partition by "pharmacy_id", "status" order by ts, End_ts rows unbounded preceding) as Crt_Total_ts,
      ts,
      "pharmacy_id", "status"
    from T1
  )
  select
    "pharmacy_id", "status",
    redundancies,
    Crt_Total_ts
  from
  (
    select
      Crt_Total_ts,
      "pharmacy_id", "status",
      int4range(ts, lead(ts) over (partition by "pharmacy_id", "status" order by ts )) as redundancies
    from T2
  ) tt
  where Crt_Total_ts >1 and redundancies <> 'empty' and upper(redundancies) is not null;

-- Temporal contradiction view for pharmacy_entertime_history
/* QUERYNAME=ContradictionUnfoldfold */
create or replace view "mimiciv_hosp@V@UHF".rctr_pharmacy_entertime_history as
  with unpack as
    (
      select "pharmacy_id"
        , "entertime"
        , "UHF".unfold("validTime") as point
      from "mimiciv_hosp@V@UHF".pharmacy_entertime_history
    ),
    anomalies as
      (
        select "pharmacy_id"
             , point
             , array_agg(distinct "entertime") as contradictions
        from unpack
        group by "pharmacy_id", point
        having count("entertime") > 1
      )
  select "pharmacy_id"
       , contradictions
       , unnest("UHF".fold("UHF".interval_cons(point,point))) as during
  from anomalies
  where array_length(contradictions, 1) > 1
  group by "pharmacy_id", contradictions;

-- Temporal contradiction view for : pharmacy_entertime_history
/* QUERYNAME=ContradictionWindowFunction */
create or replace view "mimiciv_hosp@V@UHF".wf_rctr_pharmacy_entertime_history as
  with T1 (Start_ts, End_ts, ts, pharmacy_id) as (
    select
      1,
      0,
      lower("validTime"),
      "pharmacy_id"
    from "mimiciv_hosp@V@UHF".pharmacy_entertime_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "pharmacy_id"
    from "mimiciv_hosp@V@UHF".pharmacy_entertime_history
  ),
  T2 (Crt_Total_ts, ts, pharmacy_id) as (
    select
      sum(Start_ts) over (
        partition by "pharmacy_id"
        order by ts, End_ts
        rows unbounded preceding
      )
      - sum(End_ts) over (
        partition by "pharmacy_id"
        order by ts, End_ts
        rows unbounded preceding
      ) as Crt_Total_ts,
      ts,
      "pharmacy_id"
    from T1
  )
  select
    r."pharmacy_id",
    array_agg(distinct s."entertime") as entertime_contradictions,
    r.contradictions
  from "mimiciv_hosp@V@UHF".pharmacy_entertime_history as s
  inner join (
    select
      "pharmacy_id",
      contradictions
    from (
      select
        Crt_Total_ts,
        "pharmacy_id",
        int4range(ts, lead(ts) over (
          partition by "pharmacy_id"
          order by ts
        )) as contradictions
      from T2
    ) tt
    where Crt_Total_ts > 0
      and contradictions <> 'empty'
      and upper(contradictions) is not null
  ) r
  on (
    s."pharmacy_id" = r."pharmacy_id"
    and r.contradictions <@ s."validTime"
  )
  group by r."pharmacy_id", r.contradictions
  having count(distinct s."entertime") > 1;

