create or replace view "mimiciv_hosp@V@UHF".wf_pharmacy_entertime_history_pharmacy_history as
  with T1 (Start_ts, End_ts, ts, pharmacy_id, "validTime", source) as (
    select
      1,
      0,
      lower("validTime"),
      "pharmacy_id",
      "validTime",
      'pharmacy_entertime_history' as source
    from "mimiciv_hosp@V@UHF".pharmacy_entertime_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "pharmacy_id",
      "validTime",
      'pharmacy_entertime_history' as source
    from "mimiciv_hosp@V@UHF".pharmacy_entertime_history
    union all
    select
      1,
      0,
      lower("validTime"),
      "pharmacy_id",
      "validTime",
      'pharmacy_history' as source
    from "mimiciv_hosp@V@UHF".pharmacy_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "pharmacy_id",
      "validTime",
      'pharmacy_history' as source
    from "mimiciv_hosp@V@UHF".pharmacy_history
  ),
  T2 as (
    select distinct
      "pharmacy_id",
      "validTime",
      source,
      int4range(ts, lead(ts) over (
        partition by "pharmacy_id"
        order by ts
      )) as T
    from T1
    window w as (partition by "pharmacy_id" order by ts)
  ),
  anomalies as (
    select
      t21."pharmacy_id",
      t22.source,
      t21.t,
      t22."validTime"
    from T2 as t21
    join T2 as t22 using ("pharmacy_id")
    where
      t21.t <@ t22."validTime"
      and t21.t <> 'empty'
  )
  select
    "pharmacy_id",
    T,
    array_agg(distinct source) as sources
  from anomalies
  group by "pharmacy_id", T
  having array_length(array_agg(distinct source), 1) = 1;

