create or replace view "mimiciv_hosp@V@UHF".rctr_poe_hadm_id_history as
  with unpack as
    (
      select "poe_id"
        , "hadm_id"
        , "UHF".unfold("validTime") as point
      from "mimiciv_hosp@V@UHF".poe_hadm_id_history
    ),
    anomalies as
      (
        select "poe_id"
             , point
             , array_agg(distinct "hadm_id") as contradictions
        from unpack
        group by "poe_id", point
        having count("hadm_id") > 1
      )
  select "poe_id"
       , contradictions
       , unnest("UHF".fold("UHF".interval_cons(point,point))) as during
  from anomalies
  where array_length(contradictions, 1) > 1
  group by "poe_id", contradictions;

-- Temporal contradiction view for : poe_hadm_id_history
/* QUERYNAME=ContradictionWindowFunction */
create or replace view "mimiciv_hosp@V@UHF".wf_rctr_poe_hadm_id_history as
  with T1 (Start_ts, End_ts, ts, poe_id) as (
    select
      1,
      0,
      lower("validTime"),
      "poe_id"
    from "mimiciv_hosp@V@UHF".poe_hadm_id_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "poe_id"
    from "mimiciv_hosp@V@UHF".poe_hadm_id_history
  ),
  T2 (Crt_Total_ts, ts, poe_id) as (
    select
      sum(Start_ts) over (
        partition by "poe_id"
        order by ts, End_ts
        rows unbounded preceding
      )
      - sum(End_ts) over (
        partition by "poe_id"
        order by ts, End_ts
        rows unbounded preceding
      ) as Crt_Total_ts,
      ts,
      "poe_id"
    from T1
  )
  select
    r."poe_id",
    array_agg(distinct s."hadm_id") as hadm_id_contradictions,
    r.contradictions
  from "mimiciv_hosp@V@UHF".poe_hadm_id_history as s
  inner join (
    select
      "poe_id",
      contradictions
    from (
      select
        Crt_Total_ts,
        "poe_id",
        int4range(ts, lead(ts) over (
          partition by "poe_id"
          order by ts
        )) as contradictions
      from T2
    ) tt
    where Crt_Total_ts > 0
      and contradictions <> 'empty'
      and upper(contradictions) is not null
  ) r
  on (
    s."poe_id" = r."poe_id"
    and r.contradictions <@ s."validTime"
  )
  group by r."poe_id", r.contradictions
  having count(distinct s."hadm_id") > 1;

-- Temporal denseness view for poe_hadm_id_history <-> poe_history
