-- Temporal denseness view for poe_hadm_id_history <-> poe_history
/* QUERYNAME=DensenessUnfoldfold */
create or replace view "mimiciv_hosp@V@UHF".wf_poe_hadm_id_history_poe_history as
  with T1 (Start_ts, End_ts, ts, poe_id, "validTime", source) as (
    select
      1,
      0,
      lower("validTime"),
      "poe_id",
      "validTime",
      'poe_hadm_id_history' as source
    from "mimiciv_hosp@V@UHF".poe_hadm_id_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "poe_id",
      "validTime",
      'poe_hadm_id_history' as source
    from "mimiciv_hosp@V@UHF".poe_hadm_id_history
    union all
    select
      1,
      0,
      lower("validTime"),
      "poe_id",
      "validTime",
      'poe_history' as source
    from "mimiciv_hosp@V@UHF".poe_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "poe_id",
      "validTime",
      'poe_history' as source
    from "mimiciv_hosp@V@UHF".poe_history
  ),
  T2 as (
    select distinct
      "poe_id",
      "validTime",
      source,
      int4range(ts, lead(ts) over (
        partition by "poe_id"
        order by ts
      )) as T
    from T1
    window w as (partition by "poe_id" order by ts)
  ),
  anomalies as (
    select
      t21."poe_id",
      t22.source,
      t21.t,
      t22."validTime"
    from T2 as t21
    join T2 as t22 using ("poe_id")
    where
      t21.t <@ t22."validTime"
      and t21.t <> 'empty'
  )
  select
    "poe_id",
    T,
    array_agg(distinct source) as sources
  from anomalies
  group by "poe_id", T
  having array_length(array_agg(distinct source), 1) = 1;

