create or replace view "mimiciv_hosp@V@UHF".wf_prescriptions_ndc_history_prescriptions_history as
  with T1 (Start_ts, End_ts, ts, pharmacy_id, drug_type, drug, "validTime", source) as (
    select
      1,
      0,
      lower("validTime"),
      "pharmacy_id", "drug_type", "drug",
      "validTime",
      'prescriptions_ndc_history' as source
    from "mimiciv_hosp@V@UHF".prescriptions_ndc_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "pharmacy_id", "drug_type", "drug",
      "validTime",
      'prescriptions_ndc_history' as source
    from "mimiciv_hosp@V@UHF".prescriptions_ndc_history
    union all
    select
      1,
      0,
      lower("validTime"),
      "pharmacy_id", "drug_type", "drug",
      "validTime",
      'prescriptions_history' as source
    from "mimiciv_hosp@V@UHF".prescriptions_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "pharmacy_id", "drug_type", "drug",
      "validTime",
      'prescriptions_history' as source
    from "mimiciv_hosp@V@UHF".prescriptions_history
  ),
  T2 as (
    select distinct
      "pharmacy_id", "drug_type", "drug",
      "validTime",
      source,
      int4range(ts, lead(ts) over (
        partition by "pharmacy_id", "drug_type", "drug"
        order by ts
      )) as T
    from T1
    window w as (partition by "pharmacy_id", "drug_type", "drug" order by ts)
  ),
  anomalies as (
    select
      t21."pharmacy_id", t21."drug_type", t21."drug",
      t22.source,
      t21.t,
      t22."validTime"
    from T2 as t21
    join T2 as t22 using ("pharmacy_id", "drug_type", "drug")
    where
      t21.t <@ t22."validTime"
      and t21.t <> 'empty'
  )
  select
    "pharmacy_id", "drug_type", "drug",
    T,
    array_agg(distinct source) as sources
  from anomalies
  group by "pharmacy_id", "drug_type", "drug", T
  having array_length(array_agg(distinct source), 1) = 1;

-- Temporal redundancy view for : prescriptions_ndc_history
/* QUERYNAME=RedundancyUnfoldfold */
create or replace view "mimiciv_hosp@V@UHF".prescriptions_ndc_history_red_ret as
  with unpack as
    (
      select "pharmacy_id", "drug_type", "drug", "ndc"
           , "UHF".unfold("validTime") as point
      from "mimiciv_hosp@V@UHF".prescriptions_ndc_history
    ),
    anomalies as
      (
        select "pharmacy_id", "drug_type", "drug", "ndc"
             , point
             , count(*) as count
        from unpack
        group by "pharmacy_id", "drug_type", "drug", "ndc", point
        having count(*) > 1
      )
  select "pharmacy_id", "drug_type", "drug", "ndc"
       , unnest("UHF".fold("UHF".interval_cons(point,point))) as redundancies
       , count
  from anomalies
  group by "pharmacy_id", "drug_type", "drug", "ndc", count;

-- Temporal redundancy view for : prescriptions_ndc_history
/* QUERYNAME=RedundancyWindowFunction */
create or replace view "mimiciv_hosp@V@UHF".prescriptions_ndc_history_rwf_red as
  with T1 (Start_ts, End_ts, ts, pharmacy_id, drug_type, drug, ndc) as (
    select
      1,
      0,
      lower("validTime"),
      "pharmacy_id", "drug_type", "drug", "ndc"
    from "mimiciv_hosp@V@UHF".prescriptions_ndc_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "pharmacy_id", "drug_type", "drug", "ndc"
    from "mimiciv_hosp@V@UHF".prescriptions_ndc_history
  ),
  T2 (Crt_Total_ts, ts, pharmacy_id, drug_type, drug, ndc) as (
    select
      sum(Start_ts) over (partition by "pharmacy_id", "drug_type", "drug", "ndc" order by ts, End_ts rows unbounded preceding)
      - sum(End_ts) over (partition by "pharmacy_id", "drug_type", "drug", "ndc" order by ts, End_ts rows unbounded preceding) as Crt_Total_ts,
      ts,
      "pharmacy_id", "drug_type", "drug", "ndc"
    from T1
  )
  select
    "pharmacy_id", "drug_type", "drug", "ndc",
    redundancies,
    Crt_Total_ts
  from
  (
    select
      Crt_Total_ts,
      "pharmacy_id", "drug_type", "drug", "ndc",
      int4range(ts, lead(ts) over (partition by "pharmacy_id", "drug_type", "drug", "ndc" order by ts )) as redundancies
    from T2
  ) tt
  where Crt_Total_ts >1 and redundancies <> 'empty' and upper(redundancies) is not null;

-- Temporal contradiction view for prescriptions_prod_strength_history
/* QUERYNAME=ContradictionUnfoldfold */
create or replace view "mimiciv_hosp@V@UHF".rctr_prescriptions_prod_strength_history as
  with unpack as
    (
      select "pharmacy_id", "drug_type", "drug"
        , "prod_strength"
        , "UHF".unfold("validTime") as point
      from "mimiciv_hosp@V@UHF".prescriptions_prod_strength_history
    ),
    anomalies as
      (
        select "pharmacy_id", "drug_type", "drug"
             , point
             , array_agg(distinct "prod_strength") as contradictions
        from unpack
        group by "pharmacy_id", "drug_type", "drug", point
        having count("prod_strength") > 1
      )
  select "pharmacy_id", "drug_type", "drug"
       , contradictions
       , unnest("UHF".fold("UHF".interval_cons(point,point))) as during
  from anomalies
  where array_length(contradictions, 1) > 1
  group by "pharmacy_id", "drug_type", "drug", contradictions;

-- Temporal contradiction view for : prescriptions_prod_strength_history
/* QUERYNAME=ContradictionWindowFunction */
create or replace view "mimiciv_hosp@V@UHF".wf_rctr_prescriptions_prod_strength_history as
  with T1 (Start_ts, End_ts, ts, pharmacy_id, drug_type, drug) as (
    select
      1,
      0,
      lower("validTime"),
      "pharmacy_id", "drug_type", "drug"
    from "mimiciv_hosp@V@UHF".prescriptions_prod_strength_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "pharmacy_id", "drug_type", "drug"
    from "mimiciv_hosp@V@UHF".prescriptions_prod_strength_history
  ),
  T2 (Crt_Total_ts, ts, pharmacy_id, drug_type, drug) as (
    select
      sum(Start_ts) over (
        partition by "pharmacy_id", "drug_type", "drug"
        order by ts, End_ts
        rows unbounded preceding
      )
      - sum(End_ts) over (
        partition by "pharmacy_id", "drug_type", "drug"
        order by ts, End_ts
        rows unbounded preceding
      ) as Crt_Total_ts,
      ts,
      "pharmacy_id", "drug_type", "drug"
    from T1
  )
  select
    r."pharmacy_id", r."drug_type", r."drug",
    array_agg(distinct s."prod_strength") as prod_strength_contradictions,
    r.contradictions
  from "mimiciv_hosp@V@UHF".prescriptions_prod_strength_history as s
  inner join (
    select
      "pharmacy_id", "drug_type", "drug",
      contradictions
    from (
      select
        Crt_Total_ts,
        "pharmacy_id", "drug_type", "drug",
        int4range(ts, lead(ts) over (
          partition by "pharmacy_id", "drug_type", "drug"
          order by ts
        )) as contradictions
      from T2
    ) tt
    where Crt_Total_ts > 0
      and contradictions <> 'empty'
      and upper(contradictions) is not null
  ) r
  on (
    s."pharmacy_id" = r."pharmacy_id"
        and s."drug_type" = r."drug_type"
        and s."drug" = r."drug"
    and r.contradictions <@ s."validTime"
  )
  group by r."pharmacy_id", r."drug_type", r."drug", r.contradictions
  having count(distinct s."prod_strength") > 1;

