-- Temporal contradiction view for : prescriptions_route_history
/* QUERYNAME=ContradictionWindowFunction */
create or replace view "mimiciv_hosp@V@UHF".wf_rctr_prescriptions_route_history as
  with T1 (Start_ts, End_ts, ts, pharmacy_id, drug_type, drug) as (
    select
      1,
      0,
      lower("validTime"),
      "pharmacy_id", "drug_type", "drug"
    from "mimiciv_hosp@V@UHF".prescriptions_route_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "pharmacy_id", "drug_type", "drug"
    from "mimiciv_hosp@V@UHF".prescriptions_route_history
  ),
  T2 (Crt_Total_ts, ts, pharmacy_id, drug_type, drug) as (
    select
      sum(Start_ts) over (
        partition by "pharmacy_id", "drug_type", "drug"
        order by ts, End_ts
        rows unbounded preceding
      )
      - sum(End_ts) over (
        partition by "pharmacy_id", "drug_type", "drug"
        order by ts, End_ts
        rows unbounded preceding
      ) as Crt_Total_ts,
      ts,
      "pharmacy_id", "drug_type", "drug"
    from T1
  )
  select
    r."pharmacy_id", r."drug_type", r."drug",
    array_agg(distinct s."route") as route_contradictions,
    r.contradictions
  from "mimiciv_hosp@V@UHF".prescriptions_route_history as s
  inner join (
    select
      "pharmacy_id", "drug_type", "drug",
      contradictions
    from (
      select
        Crt_Total_ts,
        "pharmacy_id", "drug_type", "drug",
        int4range(ts, lead(ts) over (
