  with T1 (Start_ts, End_ts, ts, hadm_id, transfertime, curr_service) as (
    select
      1,
      0,
      lower("validTime"),
      "hadm_id", "transfertime", "curr_service"
    from "mimiciv_hosp@V@UHF".services_prev_service_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "hadm_id", "transfertime", "curr_service"
    from "mimiciv_hosp@V@UHF".services_prev_service_history
  ),
  T2 (Crt_Total_ts, ts, hadm_id, transfertime, curr_service) as (
    select
      sum(Start_ts) over (
        partition by "hadm_id", "transfertime", "curr_service"
        order by ts, End_ts
        rows unbounded preceding
      )
      - sum(End_ts) over (
        partition by "hadm_id", "transfertime", "curr_service"
        order by ts, End_ts
        rows unbounded preceding
      ) as Crt_Total_ts,
      ts,
      "hadm_id", "transfertime", "curr_service"
    from T1
  )
  select
    r."hadm_id", r."transfertime", r."curr_service",
    array_agg(distinct s."prev_service") as prev_service_contradictions,
    r.contradictions
  from "mimiciv_hosp@V@UHF".services_prev_service_history as s
  inner join (
    select
      "hadm_id", "transfertime", "curr_service",
      contradictions
    from (
      select
        Crt_Total_ts,
        "hadm_id", "transfertime", "curr_service",
        int4range(ts, lead(ts) over (
          partition by "hadm_id", "transfertime", "curr_service"
          order by ts
        )) as contradictions
      from T2
    ) tt
    where Crt_Total_ts > 0
      and contradictions <> 'empty'
      and upper(contradictions) is not null
  ) r
  on (
    s."hadm_id" = r."hadm_id"
        and s."transfertime" = r."transfertime"
        and s."curr_service" = r."curr_service"
    and r.contradictions <@ s."validTime"
  )
  group by r."hadm_id", r."transfertime", r."curr_service", r.contradictions
  having count(distinct s."prev_service") > 1;

