create or replace view "mimiciv_hosp@V@UHF".wf_services_prev_service_history_services_history as
  with T1 (Start_ts, End_ts, ts, hadm_id, transfertime, curr_service, "validTime", source) as (
    select
      1,
      0,
      lower("validTime"),
      "hadm_id", "transfertime", "curr_service",
      "validTime",
      'services_prev_service_history' as source
    from "mimiciv_hosp@V@UHF".services_prev_service_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "hadm_id", "transfertime", "curr_service",
      "validTime",
      'services_prev_service_history' as source
    from "mimiciv_hosp@V@UHF".services_prev_service_history
    union all
    select
      1,
      0,
      lower("validTime"),
      "hadm_id", "transfertime", "curr_service",
      "validTime",
      'services_history' as source
    from "mimiciv_hosp@V@UHF".services_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "hadm_id", "transfertime", "curr_service",
      "validTime",
      'services_history' as source
    from "mimiciv_hosp@V@UHF".services_history
  ),
  T2 as (
    select distinct
      "hadm_id", "transfertime", "curr_service",
      "validTime",
      source,
      int4range(ts, lead(ts) over (
        partition by "hadm_id", "transfertime", "curr_service"
        order by ts
      )) as T
    from T1
    window w as (partition by "hadm_id", "transfertime", "curr_service" order by ts)
  ),
  anomalies as (
    select
      t21."hadm_id", t21."transfertime", t21."curr_service",
      t22.source,
      t21.t,
      t22."validTime"
    from T2 as t21
    join T2 as t22 using ("hadm_id", "transfertime", "curr_service")
    where
      t21.t <@ t22."validTime"
      and t21.t <> 'empty'
  )
  select
    "hadm_id", "transfertime", "curr_service",
    T,
    array_agg(distinct source) as sources
  from anomalies
  group by "hadm_id", "transfertime", "curr_service", T
  having array_length(array_agg(distinct source), 1) = 1;

