create or replace view "mimiciv_hosp@V@UHF".poe_detail_subject_id_history_red_ret as
  with unpack as
    (
      select "poe_id", "field_name", "subject_id"
           , "UHF".unfold("validTime") as point
      from "mimiciv_hosp@V@UHF".poe_detail_subject_id_history
    ),
    anomalies as
      (
        select "poe_id", "field_name", "subject_id"
             , point
             , count(*) as count
        from unpack
        group by "poe_id", "field_name", "subject_id", point
        having count(*) > 1
      )
  select "poe_id", "field_name", "subject_id"
       , unnest("UHF".fold("UHF".interval_cons(point,point))) as redundancies
       , count
  from anomalies
  group by "poe_id", "field_name", "subject_id", count;

-- Temporal redundancy view for : poe_detail_subject_id_history
/* QUERYNAME=RedundancyWindowFunction */
create or replace view "mimiciv_hosp@V@UHF".poe_detail_subject_id_history_rwf_red as
  with T1 (Start_ts, End_ts, ts, poe_id, field_name, subject_id) as (
    select
      1,
      0,
      lower("validTime"),
      "poe_id", "field_name", "subject_id"
    from "mimiciv_hosp@V@UHF".poe_detail_subject_id_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "poe_id", "field_name", "subject_id"
    from "mimiciv_hosp@V@UHF".poe_detail_subject_id_history
  ),
  T2 (Crt_Total_ts, ts, poe_id, field_name, subject_id) as (
    select
      sum(Start_ts) over (partition by "poe_id", "field_name", "subject_id" order by ts, End_ts rows unbounded preceding)
      - sum(End_ts) over (partition by "poe_id", "field_name", "subject_id" order by ts, End_ts rows unbounded preceding) as Crt_Total_ts,
      ts,
      "poe_id", "field_name", "subject_id"
    from T1
  )
  select
    "poe_id", "field_name", "subject_id",
    redundancies,
    Crt_Total_ts
  from
  (
    select
      Crt_Total_ts,
      "poe_id", "field_name", "subject_id",
      int4range(ts, lead(ts) over (partition by "poe_id", "field_name", "subject_id" order by ts )) as redundancies
    from T2
  ) tt
  where Crt_Total_ts >1 and redundancies <> 'empty' and upper(redundancies) is not null;

-- Temporal contradiction view for poe_detail_field_value_history
/* QUERYNAME=ContradictionUnfoldfold */
create or replace view "mimiciv_hosp@V@UHF".rctr_poe_detail_field_value_history as
  with unpack as
    (
      select "poe_id", "field_name"
        , "field_value"
        , "UHF".unfold("validTime") as point
      from "mimiciv_hosp@V@UHF".poe_detail_field_value_history
    ),
    anomalies as
      (
        select "poe_id", "field_name"
             , point
             , array_agg(distinct "field_value") as contradictions
        from unpack
        group by "poe_id", "field_name", point
        having count("field_value") > 1
      )
  select "poe_id", "field_name"
       , contradictions
       , unnest("UHF".fold("UHF".interval_cons(point,point))) as during
  from anomalies
  where array_length(contradictions, 1) > 1
  group by "poe_id", "field_name", contradictions;

-- Temporal contradiction view for : poe_detail_field_value_history
/* QUERYNAME=ContradictionWindowFunction */
create or replace view "mimiciv_hosp@V@UHF".wf_rctr_poe_detail_field_value_history as
  with T1 (Start_ts, End_ts, ts, poe_id, field_name) as (
    select
      1,
      0,
      lower("validTime"),
      "poe_id", "field_name"
    from "mimiciv_hosp@V@UHF".poe_detail_field_value_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "poe_id", "field_name"
    from "mimiciv_hosp@V@UHF".poe_detail_field_value_history
  ),
  T2 (Crt_Total_ts, ts, poe_id, field_name) as (
    select
      sum(Start_ts) over (
        partition by "poe_id", "field_name"
        order by ts, End_ts
        rows unbounded preceding
      )
      - sum(End_ts) over (
        partition by "poe_id", "field_name"
        order by ts, End_ts
        rows unbounded preceding
      ) as Crt_Total_ts,
      ts,
      "poe_id", "field_name"
    from T1
  )
  select
    r."poe_id", r."field_name",
    array_agg(distinct s."field_value") as field_value_contradictions,
    r.contradictions
  from "mimiciv_hosp@V@UHF".poe_detail_field_value_history as s
  inner join (
    select
      "poe_id", "field_name",
      contradictions
    from (
      select
        Crt_Total_ts,
        "poe_id", "field_name",
        int4range(ts, lead(ts) over (
          partition by "poe_id", "field_name"
          order by ts
        )) as contradictions
      from T2
    ) tt
    where Crt_Total_ts > 0
      and contradictions <> 'empty'
      and upper(contradictions) is not null
  ) r
  on (
    s."poe_id" = r."poe_id"
        and s."field_name" = r."field_name"
    and r.contradictions <@ s."validTime"
  )
  group by r."poe_id", r."field_name", r.contradictions
  having count(distinct s."field_value") > 1;

-- Temporal denseness view for poe_detail_field_value_history <-> poe_detail_history
/* QUERYNAME=DensenessUnfoldfold */
create or replace view "mimiciv_hosp@V@UHF".dert_poe_detail_field_value_history_poe_detail_history as
  with unpack as
    (
      select "poe_id", "field_name"
           , "UHF".unfold("validTime") as point
           , 'poe_detail_field_value_history' as source
      from "mimiciv_hosp@V@UHF".poe_detail_field_value_history
      union
      select "poe_id", "field_name"
           , "UHF".unfold("validTime") as point
           , 'poe_detail_history' as source
      from "mimiciv_hosp@V@UHF".poe_detail_history
    ),
    anomalies as
    (
      select "poe_id", "field_name"
           , point
           , array_agg(distinct source) as sources
      from unpack
      group by "poe_id", "field_name", point
    )
  select "poe_id", "field_name"
       , unnest("UHF".fold("UHF".interval_cons(point,point))) as during
       , sources
  from anomalies
  where array_length(sources, 1) < 2
  group by "poe_id", "field_name", sources;

-- Temporal denseness view for poe_detail_field_value_history <-> poe_detail_history
/* QUERYNAME=DensenessUnfoldfold */
create or replace view "mimiciv_hosp@V@UHF".wf_poe_detail_field_value_history_poe_detail_history as
  with T1 (Start_ts, End_ts, ts, poe_id, field_name, "validTime", source) as (
    select
      1,
      0,
      lower("validTime"),
      "poe_id", "field_name",
      "validTime",
      'poe_detail_field_value_history' as source
    from "mimiciv_hosp@V@UHF".poe_detail_field_value_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "poe_id", "field_name",
      "validTime",
      'poe_detail_field_value_history' as source
    from "mimiciv_hosp@V@UHF".poe_detail_field_value_history
    union all
    select
      1,
      0,
      lower("validTime"),
      "poe_id", "field_name",
      "validTime",
      'poe_detail_history' as source
    from "mimiciv_hosp@V@UHF".poe_detail_history
    union all
    select
      0,
      1,
      upper("validTime"),
      "poe_id", "field_name",
      "validTime",
      'poe_detail_history' as source
    from "mimiciv_hosp@V@UHF".poe_detail_history
  ),
  T2 as (
    select distinct
      "poe_id", "field_name",
      "validTime",
      source,
      int4range(ts, lead(ts) over (
        partition by "poe_id", "field_name"
        order by ts
      )) as T
    from T1
    window w as (partition by "poe_id", "field_name" order by ts)
  ),
  anomalies as (
    select
      t21."poe_id", t21."field_name",
      t22.source,
      t21.t,
      t22."validTime"
    from T2 as t21
    join T2 as t22 using ("poe_id", "field_name")
    where
      t21.t <@ t22."validTime"
      and t21.t <> 'empty'
  )
  select
    "poe_id", "field_name",
    T,
    array_agg(distinct source) as sources
  from anomalies
  group by "poe_id", "field_name", T
  having array_length(array_agg(distinct source), 1) = 1;

